 11	 */
 12	public abstract class Predator extends Animal {
 13	
 14	    // define fields
 15	
 16	    // shared random generator to generate consistent results
 17	    private static final Random rand = Randomizer.getRandom();
 18	
 19	    private int foodLevel;
 20	
 21	    /**
 22	     * Constructor for a predator in the simulation.
 23	     *
 24	     * @param foodLevel The food level of this predator.
 25	     * @param randomAge Whether the predator should have a random age or not.
 26	     * @param field The field in which the predator resides.
 27	     * @param location The location in which the predator spawns into.
 28	     */
 29	    public Predator(int foodLevel, boolean randomAge, Field field, Location location) {
 30	        super(randomAge, field, location);
 31	
 32	        this.foodLevel = foodLevel;
 33	    }
 34	
 35	    /**
 36	     * Abstract method for what the predator does, i.e. what is always run at every step.
 37	     *
 38	     * @param newPredators A list of all newborn predators in this simulation step.
 39	     * @param weather The current state of weather in the simulation.
 40	     * @param time The current state of time in the simulation.
 41	     */
 42	    @Override
 43	    public void act(List<Organism> newPredators, Weather weather, TimeOfDay time) {
 44	        incrementAge();
 45	        incrementHunger();
 46	        if(isAlive()) {
 47	            giveBirth(newPredators);
 48	
 49	            if (isRestingTime(time)) {
 50	                return;
 51	            }
 52	
 53	            if (rand.nextDouble() <= getDeathByDiseaseProbability() ) {
 54	                remove();
 55	                return;
 56	            }
 57	
 58	            Location newLocation = chooseTargetLocation();
 59	            if(newLocation == null) {
 60	                newLocation = getField().freeAdjacentLocation(getLocation());
 61	            }
 62	
 63	            if(newLocation != null) {
 64	                setLocation(newLocation);
 65	            }
 66	            else {
 67	                remove();
 68	            }
 69	        }
 70	    }
 71	
 72	    /**
 73	     * Finds the nearest food source and returns its location.
 74	     *
 75	     * @return Location of food source.
 76	     */
 77	    @Override
 78	    public Location findFood() {
 79	        Field field = getField();
 80	        List<Location> adjacent = field.adjacentLocations(getLocation());
 81	        Iterator<Location> it = adjacent.iterator();
 82	        while(it.hasNext()) {
 83	            Location where = it.next();
 84	
 85	            Organism animal = field.getOrganismAt(where);
 86	            if(animal instanceof Prey) {
 87	                Prey prey = (Prey) animal;
 88	                if (prey.isAlive()) {
 89	                    // kills animal
 90	                    prey.setDead();
 91	                    // random chance to eat
 92	                    boolean eaten = eat(prey);
 93	
 94	                    return eaten ? where : null;
 95	                }
 96	            }
 97	        }
 98	        return null;
 99	    }
100	
101	    /**
102	     * Getter method to return this predator's probability of eating if food is found.
103	     *
104	     * @return The predator's eating probability.
105	     */
106	    abstract public double getEatingProbability();
107	
108	    /**
109	     * Called when a predator either eats or leaves a prey it
110	     * has killed.
111	     *
112	     * @param consumable The prey to be eaten.
113	     * @return Whether the prey has been eaten or not.
114	     */
115	    @Override
116	    public boolean eat(Consumable consumable) {
117	        if (rand.nextDouble() <= getEatingProbability()) {
118	            incrementFoodLevel(consumable.getFoodValue());
119	            consumable.setEaten();
120	            //System.out.println("EATEN PREY");
121	            return true;
122	        } else {
123	            //System.out.println("LEFT PREY");
124	            return false;
125	        }
126	    }
127	
128	    /**
129	     * Increase the predator's food level by a given integer amount.
130	     *
131	     * @param foodLevel The value to increment food level by.
132	     */
133	    public void incrementFoodLevel(int foodLevel) {
134	        this.foodLevel += foodLevel;
135	    }
136	
137	    /**
138	     * Make this predator more hungry. This could result in the predator's death.
139	     */
140	    public void incrementHunger() {
141	        foodLevel--;
142	        if (foodLevel <= 0) {
143	            remove();
144	        }
145	    }
146	
147	    private Location chooseTargetLocation() {
148	        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
149	            return findAnimalToInfect();
150	        }
151	        return findFood();
152	    }
153	
154	    protected abstract boolean isRestingTime(TimeOfDay time);
155	}

