 11	public abstract class Prey extends Animal implements Consumable {
 12	
 13	    // define fields
 14	    private static final double DEFAULT_ACTIVENESS = 1;
 15	    private static final Random rand = Randomizer.getRandom();
 16	    private int foodValue;
 17	    private double activeness;  // denotes how likely it is for the act method to be called
 18	
 19	    /**
 20	     * Constructor for a Prey in the simulation.
 21	     *
 22	     * @param foodValue The value of food of this prey.
 23	     * @param randomAge Whether we assign this prey a random age or not.
 24	     * @param field The field in which this prey resides.
 25	     * @param location The location in which this prey is spawned into.
 26	     */
 27	    public Prey(int foodValue, boolean randomAge, Field field, Location location) {
 28	        super(randomAge, field, location);
 29	
 30	        this.foodValue = foodValue;
 31	        this.activeness = DEFAULT_ACTIVENESS;
 32	    }
 33	
 34	    /**
 35	     * Method for what the prey does, i.e. what is always run at every step.
 36	     *
 37	     * @param newPrey A list of all newborn prey in this simulation step.
 38	     * @param weather The current state of weather in the simulation.
 39	     * @param time The current state of time in the simulation.
 40	     */
 41	    @Override
 42	    public void act(List<Organism> newPrey, Weather weather, TimeOfDay time) {
 43	        incrementAge();
 44	        setActiveness(getActivenessFor(time));
 45	
 46	        if(isAlive()) {
 47	            giveBirth(newPrey);
 48	
 49	            if (rand.nextDouble() <= getDeathByDiseaseProbability() ) {
 50	                remove();
 51	                return;
 52	            }
 53	
 54	            if (rand.nextDouble() <= getActiveness()){
 55	                Location newLocation = chooseTargetLocation();
 56	                if ((newLocation == null) || (getFoodValue() > 10)) {
 57	                    newLocation = getField().freeAdjacentLocation(getLocation());
 58	                }
 59	
 60	                if(newLocation != null) {
 61	                    setLocation(newLocation);
 62	                }
 63	                else {
 64	                    remove();
 65	                }
 66	            }
 67	        } else {
 68	            decayifDead();
 69	        }
 70	    }
 71	
 72	    /**
 73	     * Clear the prey from the simulation as it has been eaten.
 74	     */
 75	    @Override
