100	     * @param consumable The plant to be eaten.
101	     * @return Whether the plant was eaten.
102	     */
103	    @Override
104	    public boolean eat(Consumable consumable) {
105	        if ((consumable.isPoisonous()) && (!isInfected())) {
106	            infect(this);
107	        }
108	        incrementFoodValue(consumable.getFoodValue());
109	        consumable.setEaten();
110	        return true;
111	    }
