139	    /**
140	     * Find a nearby plant and consume it if possible.
141	     *
142	     * @return The location of the food source, or null if none was eaten.
143	     */
144	    protected Location findPlantFood() {
145	        Field field = getField();
146	        for (Location where : field.adjacentLocations(getLocation())) {
147	            Organism organism = field.getOrganismAt(where);
148	            if (organism instanceof Plant) {
149	                Plant plant = (Plant) organism;
150	                if (plant.isAlive()) {
151	                    plant.setDead();
152	                    return eat(plant) ? where : null;
153	                }
154	            }
155	        }
156	        return null;
157	    }
