160	        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
161	            return findAnimalToInfect();
162	        }
163	        return findFood();
164	    }
165	
166	    protected double getActivenessFor(TimeOfDay time) {
167	        return DEFAULT_ACTIVENESS;
168	    }
